INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('F0001', 'African Orchid', 'Rare Delicate Beauty', 'African orchids are some of the most endangered and rare kinds of orchids grown today. This variety is medium yellow with varigated salmon and pink insides. Height: 18 to 28 inches.', 'per plant', 'flower_african_orchid.jpg', CAST(X'' AS BLOB), 250.0, 145.0, 0, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('F0002', 'Baby Breath', 'Ethereal White Elegance', '(Gypsophila muralis). Small, delicate Baby Breath flowers create clouds of accents in floral arrangements or beautiful lacy designs when used alone. Can be used fresh or dried. Height: 12 to 18 inches.', '2 plants', 'flower_bbreath.jpg', CAST(X'' AS BLOB), 6.0, 2.0, 0, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('F0003', 'Black-eyed Susan', 'Radiant, like the Sun', '(Rudbeckia hirta). The Black-Eyed Susan was made the official Maryland flower in 1918.  Typically they grow wild -- and bloom between May and August -- but you can purchase them as a permanent addition to your own garden. Height: 2 to 3 feet.', '2 plants', 'flower_black-eyed_susan.jpg', CAST(X'' AS BLOB), 9.0, 2.0, 0, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('F0004', 'Coleus', 'Colorful Accent', '(Coleus blumei). An attractive foliage plant, the Coleus is especially suited for containers and underplantings. While it can tolerate the sun, the color of leaves is enhanced in partial to full shade. Height: 12 inches to 36 inches.', '4 plants', 'flower_coleus.jpg', CAST(X'' AS BLOB), 8.0, 3.0, 0, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('F0005', 'Yellow Shasta Daisy', 'Charming Simple Beauty', '(Bellis perenis). Oversized blossoms in bright yellow with a very long bloom period. For extra decoration, cut the stems and place in food coloring and water to make vibrantly colored cut flowers. Height: 1 to 3 feet.', '2 plants', 'flower_daisies.jpg', CAST(X'' AS BLOB), 16.0, 2.5, 0, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('F0006', 'Perennial Foxglove', 'Showy Thimble-like Blooms', '(Digitalis). Foxglove grows best in shade and works well as a tall, showy flower that lights up a dark garden area. The individual flowers are sized and shaped like thimbles. Height: 2 to 3 feet.', '3 plants', 'flower_foxglove.jpg', CAST(X'' AS BLOB), 12.0, 2.75, 0, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('F0007', 'Geranium', 'Red and Flowery', '(Geranium sanguineum). This bright red version of the Bloody Cranesbill Geranium has small, bright green foliage that adds dimension and sets off the vibrant colored flowers. Assembled. Height: 8 inches.', 'per plant', 'flower_geranium.jpg', CAST(X'' AS BLOB), 8.0, 2.3, 0, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('F0008', 'Goodnight Moon Iris', 'Fluorescent Bloomer', 'Iris provides lovely cut flowers which brighten rainy spring days. When the Iris has stopped blossoming, cut off dead blossoms and dead bloom stalks, but do not cut back the leaves until they begin to turn brown in the Fall.', '5 bulbs', 'flower_goodnight_moon_iris.jpg', CAST(X'' AS BLOB), 7.5, 3.6, 0, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('F0009', 'Impatiens', 'Tangerine Dream', '(Impatiens walleriana). Vibrant tangerine-orange flowers coordinate nicely with green foliage. Impatiens is a great annual for beds, borders, containers and hanging baskets. Grow in full sun to partial shade.  Height: 15 to 20 inches.', '2 plants', 'flower_impatiens.jpg', CAST(X'' AS BLOB), 9.95, 1.25, 0, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('F0010', 'Lily', 'Purple Summer Glory', '(Hemerocallis fulva) Magnificent flowers up to 3 inches or more across. Blooms start June through August, depending on variety, and have a subtle fragrance. Tolerates dry soil but it is wise to water deeply during periods of dry weather.', '4 bulbs', 'flower_lily.jpg', CAST(X'' AS BLOB), 6.5, 3.25, 0, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('F0011', 'Pansy', 'Autumn Mix', '(Viola tricolor). Reminiscent of the colors of fall.  Our Pansies will bloom from fall to early winter, and again in the spring! They prefer part shade to full sun. Height 6 to 8 inches.', '1 pkt. (25 seeds)', 'flower_pansies.jpg', CAST(X'' AS BLOB), 2.0, 1.25, 0, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('F0012', 'Petunia', 'Striped Brightness', '(Petunia x hybrida). Striking, large magenta flowers with contrasting white trumpet stripes. Excellent for borders, window boxes, planters and bouquets.  Petunias do best in full sun but will tolerate light shade. Height: 1 foot.', '1 pkt. (50 seeds)', 'flower_petunias.jpg', CAST(X'' AS BLOB), 3.0, 1.25, 0, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('F0013', 'Primrose', 'Means: I Cannot Live Without You', '(Primula). Large, fragrant blooms in wide-eyed spring like yellow. Plants thrive despite heat and drought and require good drainage. Height: 12 inches.', '6 plants', 'flower_primrose.jpg', CAST(X'' AS BLOB), 10.0, 4.75, 0, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('F0014', 'Red Poinsettia', 'Seasonal Beauty', '(Euphorbia pulcherrima). Lush red flowers float atop deep green leaves. They were first developed in Mexico and need warm temperatures and full sun. Height: 2 to 3 feet.', 'per plant', 'flower_red_poinsettia.jpg', CAST(X'' AS BLOB), 11.0, 4.5, 0, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('F0015', 'Red Rose', 'Always in Bloom', '(Rosa Floribunda). Created in France (1956), this rose continually produces boldly colored, medium-sized red blooms.  Intensely fragrant. Includes thorns and songs about lost love. Height: 10 - 12 feet.', 'per vine', 'flower_red_rose.jpg', CAST(X'' AS BLOB), 32.0, 15.0, 0, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('F0016', 'Sparkler Celosia', 'Brilliant Flames of Red Fire', '(Celosia plumosa). Excellent for cutting, these Sparkler Celosia have brilliant 6 inch plumes. They are a perfect companion for full-sun garden beds or in fresh or dried bouquets. Height: 2 to 2.5 feet.', '4 plants', 'flower_sparkler_celosia.jpg', CAST(X'' AS BLOB), 7.0, 3.25, 0, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('F0017', 'Tulip', 'Mixed Dutch Delight', '(Tulipa). Out famous tulip bulbs are supplied by one of the finest Dutch bulb growers. Mixed colors resonate on even the cloudiest of days. These bulbs are of the highest quality and are guaranteed. Height: 10 to 12 inches.', '10 bulbs', 'flower_tulips.jpg', CAST(X'' AS BLOB), 17.0, 9.0, 0, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('F0018', 'White Poinsettia', 'Seasonal Simplicity', '(Euphorbia pulcherrima). A rich color of deep green leaves support large bright white blossoms. Poinsettias were first developed in Mexico and need full sun. Height: 2 to 3 feet.', 'per plant', 'flower_white_poinsettia.jpg', CAST(X'' AS BLOB), 14.0, 5.5, 0, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('F0019', 'White Rose', 'A Classic Beauty', '(Rosa Floribunda).  Classic, white buds open into double blooms of palest pink to white on this rose created in 1888 France. Thornless. Height: 4 to 5 feet.', 'per vine', 'flower_white_rose.jpg', CAST(X'' AS BLOB), 37.0, 17.0, 0, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('F0020', 'Zinnia', 'You cut more, they bloom more!', '(Zinnia elegans). Zinnias add bold, vibrant color to gardens. They are heat loving and prefer full-sun. Perfect for beds and cut floral arrangements. They even attract butterflies! Height: 12 to 18 inches.', '12 plants', 'flower_zinnia.jpg', CAST(X'' AS BLOB), 7.95, 3.95, 0, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('A0001', 'Bulb Digger', 'Pick The Right Tool For The Right Job', 'Simplifies digging holes for poles, posts, and many other jobs. Tempered steel even breaks through rock. Long, coated 54 inch hardwood handle.', 'Assembled', 'accessories_bulbdigger.jpg', CAST(X'' AS BLOB), 12.0, 5.0, 3, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('A0002', 'Birdfeeder', 'Birds of a Feather Feed Together', 'Hexagon shaped bird feeder stores food upright which allows more birds to feed and gives you the best view! Natural wood base supports clear plastic lenses on all 5 sides. Ready to be hung or mounted on a pole (not included).', 'Pole not included', 'accessories_birdfeeder.jpg', CAST(X'' AS BLOB), 16.0, 7.0, 3, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('A0003', 'Birdhouse', 'Ideal for Nesting Birds', 'Wooden birdhouse perfect for nesting birds and their companions. Made of naturally weather resistant pine with a sloped roof. Mounting hardware and instructions included. Height: 18 inches. Width: 10 inches.', 'Assembled', 'accessories_birdhouse.jpg', CAST(X'' AS BLOB), 12.0, 6.0, 3, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('A0004', 'Finch Food', 'Attracts Fabulous Finches', 'Bird feed especially formulated for finches, as well as other small birds. No seeds are wasted; birds will like them all.', '20 lb. bag', 'accessories_finchfood.jpg', CAST(X'' AS BLOB), 6.5, 2.0, 3, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('A0005', 'Grass Rake', 'Put the Kids to Work', 'Welded bow rake is heat treated for strength. Long, coated 54 inch hardwood handle. Use it to level and break up clumps of soil, remove debris, and spread topsoil or compost. 5 year limited warranty.', 'Assembled', 'accessories_grassrake.jpg', CAST(X'' AS BLOB), 6.0, 2.5, 3, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('A0006', 'Leaf Rake', 'The Ultimate Backscratcher', 'Wooden polyurethene coated handle adjusts is 32 inches long. Comfortable grip. Fully heat treated head and chip resistant carbon dioxide coating make this rake last for years.', 'Assembled', 'accessories_leafrake.jpg', CAST(X'' AS BLOB), 10.0, 4.5, 3, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('A0007', 'Shovel', 'Dig it, Man!', 'Open back tempered steel blade attached to sturdy hardwood handle with 6 inch lead.  Uses include: planting shrubs, trees, and general digging or cutting through sod or soil. Handle Length: 46 inches', 'Assembled', 'accessories_shovel.jpg', CAST(X'' AS BLOB), 7.0, 3.0, 3, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('A0008', 'Gloves', 'If The Gloves Fit, You Must Plant It', 'One size fits all.  Each carefully sewn left glove comes with an accompanying right glove. Comes in pack of 3, with colors red, green, and blue.', '3 pairs per pack', 'accessories_gloves.jpg', CAST(X'' AS BLOB), 4.5, 1.0, 3, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('A0009', 'Hand Rake', 'A Real Humdinger', 'Sometimes you have to work on your hands and knees. This tool is great for raking, digging, whatever. Handle is cushioned with rubber.', 'Assembled', 'accessories_handrake.jpg', CAST(X'' AS BLOB), 4.5, 1.5, 3, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('A0010', 'Large Pot', 'Large and, well, just Large', 'Large ceramic pot perfect for bigger plants that need to be moved in during frosts. Diameter of 18 inches - holds 5 gallon plants.', 'N/A', 'accessories_pot.jpg', CAST(X'' AS BLOB), 10.0, 3.0, 3, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('A0011', 'Wheelbarrow', 'Just like Grandpa used to have!', 'Shiny red wheelbarrow with epoxy coated steel bin and wooden handles. Tire is solid with thick treads that grip rough, wet surfaces. Large capacity - 3 Cu.Ft. capacity, 150 Lb. maximum load', 'Assembled', 'accessories_wheelbarrow.jpg', CAST(X'' AS BLOB), 29.0, 12.0, 3, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('T0001', 'Ash', 'Full and Leafy like a Lollipop', 'Large, round, summer shade leads to yellow leaves that burst through dreary Fall days! Excellent for yards. Mature height: up to 20 feet.', '10 gallon seedling', 'trees_ash.jpg', CAST(X'' AS BLOB), 50.0, 20.0, 2, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('T0002', 'Aspen', 'Tall, Slender Grace', 'White barked Aspens are particularly beautiful during white winters. Close your eyes and imagine a light breeze sailing over the trunk and the crinkling of the colliding leaves. Mature height: up to 28 feet.', '10 gallon seedling', 'trees_aspen.jpg', CAST(X'' AS BLOB), 53.0, 21.0, 2, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('T0003', 'Bonsai', 'Tabletop Fun', 'Bonsais are great miniature replicas of your favorite yard tree. They can be indoors or out -- and their size makes them perfect for tabletop decoration.', '0.5 gallon mature tree', 'trees_bonsai.jpg', CAST(X'' AS BLOB), 30.0, 12.0, 2, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('T0004', 'Crabapple', 'Short but beautiful', 'These trees light up Springtime with pink, fragrant flowers that change into crabapples.  Perfect for Maryland residents. Mature height: up to 20 feet.', '10 gallon seedling', 'trees_crab.jpg', CAST(X'' AS BLOB), 57.0, 19.0, 2, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('T0005', 'Maple', 'Traditional Shade Producer', 'Famous for their syrup, you will be able to tap into your own endless supply in just a few years. Not suitable for diabetics. Mature height: up to 24 feet.', '10 gallon seedling', 'trees_maple.jpg', CAST(X'' AS BLOB), 45.0, 22.0, 2, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('V0001', 'Cabbage', 'Crispy', 'Crispy green cabbage will poke through summer gardens about 3-4 weeks after springtime planting of seedlings. An excellent source of Vitamin A and D.', '1 pkt. (100 seeds)', 'veggies_cabbage.jpg', CAST(X'' AS BLOB), 2.0, 0.7, 1, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('V0002', 'Ornamental Gourd', 'Gourd-geous!', 'OrNAMEntal gourds are a staple for Autumn flowerbeds, door decorations, floral arrangements and tabletop centerpieces. Grow your own this year to give to your neighbors and family.', '1 pkt. (100 seeds)', 'veggies_gourds.jpg', CAST(X'' AS BLOB), 1.5, 0.7, 1, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('V0003', 'Grapes', 'Be Your Own Winemaker', 'Join others who are fermenting their own small, personal batches of wine! These vines were developed in France and their grapes make a fruity, medium white wine or a fruity Beaujolais when pressed with the skins.', '1 vine', 'veggies_grapes.jpg', CAST(X'' AS BLOB), 49.0, 20.5, 1, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('V0004', 'Onion', 'Fresh and Tasty from your Garden', 'Pure white onions are sweetest when grown at home and left in the ground until picking. Tissues not included.', '4 bulbs', 'veggies_onion.jpg', CAST(X'' AS BLOB), 9.0, 4.75, 1, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('V0005', 'Pineapple', 'Tropical Delight', 'Pineapples can be grown at home with this frost-bearing breed. Yields 4 - 5 fruits annually, more in warmer climates. Fertilize with organic compost regularly for best results. Be careful of maurading neighbors.', '8 gallon potted plant', 'veggies_pineapple.jpg', CAST(X'' AS BLOB), 87.0, 34.5, 1, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('V0006', 'Strawberries', 'Sweet Berry Scrumptiousness', 'Our brand is known for producing plump, sweet strawberries by the mid-June bucketful. Now you can grow them easily, with relatively little care, due to our patented version. Dental floss not included.', '1 pkt. (50 seeds)', 'veggies_strawberries.jpg', CAST(X'' AS BLOB), 3.5, 1.5, 1, 100, 'NOTES and stuff', 1, 50, 200);
INSERT INTO INVENTORY (INVENTORYID, NAME, HEADING, DESCRIPTION, PKGINFO, IMAGE, IMGBYTES, PRICE, COST, CATEGORY, QUANTITY, NOTES, ISPUBLIC, MINTHRESHOLD, MAXTHRESHOLD) VALUES ('V0007', 'Watermelon', 'Seedless Summer ', 'Plant our seeds indoors in late winter and transfer outside after threat of frost recedes; our seeds will produce huge, round, ripe melons by mid-June. Guaranteed not to contain active Acidophilous cultures.', '1 pkt. (100 seeds)', 'veggies_watermelon.jpg', CAST(X'' AS BLOB), 2.0, 0.5, 1, 50, 'NOTES and stuff', 1, 50, 200);
INSERT INTO SUPPLIER (SUPPLIERID, NAME, STREET, CITY, USSTATE, ZIP, PHONE, URL) VALUES ('Supplier', 'Greenhouse By WebSphere', '4205 Miami Blvd.', 'Durham', 'NC', '27709', '919-555-1212', 'http://localhost:9080/OrderProcessorEJB/services/FrontGate?wsdl');
